/**
 * How many of one level's published questions fall into each of the three
 * buckets `prioritizeHistory` draws first — how much material the setting
 * actually has to work with for this learner.
 *
 * Three numbers for what the draw treats as ONE tier: `prioritizeHistory`
 * ranks all three equally, so a client wanting "how many câu would be
 * preferred" adds them, while one wanting to say WHY still has the three
 * reasons apart.
 *
 * Counted from the exact pool `POST /custom-exams/attempts` draws from,
 * not estimated beside it (R-35).
 *
 * Whole-level totals, not per section: the setting is one control over
 * the whole draw, and three numbers per part would be nine figures behind
 * one tick box.
 *
 * Đã làm đúng is deliberately absent — it is the tier nobody turns this
 * feature on for, and it is derivable: every question at the level, less
 * these three.
 *
 * No client renders these today; kolearn-web showed them under the
 * checkbox for a while and dropped the line.
 */
export interface CustomExamHistoryCounts {
  /**
     * Answered, and answered with the wrong choice, at least once. MCQ
     * only — a phần Viết task has no choice to be wrong against.
     */
  wrong: number;
  /**
     * Served and left blank at least once, whether the paper was
     * submitted with it skipped or abandoned before it was reached. MCQ
     * only, for the same reason as `wrong`: an essay the learner actually
     * wrote has no `attempt_answers` row and would otherwise read as bỏ
     * dở for ever.
     *
     * Never overlaps `wrong`: a question that is both is counted once,
     * under `wrong`. A tie-break for the tally only — the draw ranks the
     * two the same.
     */
  unfinished: number;
  /** Never served to this learner, in any attempt. */
  unseen: number;
}
